#[test]
fn public_binding_matches_executed_fields_numbers_digests_and_extra_fields() {
    for case in fixture()["cases"].as_array().unwrap() {
        let actual = protocol::managed::validate_binding(&case["value"]);
        assert_eq!(
            actual.err().map(|e| e.0),
            case["error"].as_str(),
            "{}",
            case["name"]
        );
    }
}
#[test]
fn common_request_keeps_identifier_sequence_then_binding_error_order() {
    for case in fixture()["request_cases"].as_array().unwrap() {
        let actual = protocol::managed::validate_request_common(&case["value"]);
        assert_eq!(
            actual.err().map(|e| e.0),
            case["error"].as_str(),
            "{}",
            case["name"]
        );
    }
}
